cat vitest.config.ts tsconfig.json && cat > src/claim-office.spec.ts <<'EOF'
import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword for a 0-year newcomer → premium 115 G (100 base + 10 first insurance + 5 fee)");
    it.todo("plain amulet → premium 71 G (60 base + 6 first insurance + 5 fee)");
    it.todo("plain staff → premium 93 G (80 base + 8 first insurance + 5 fee)");
    it.todo("plain potion → premium 49 G (40 base + 4 first insurance + 5 fee)");
  });

  describe("quote — components and blocks", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — modifiers", () => {
    it.todo("cursed surcharge applies only to the cursed item: cursed sword + plain amulet → 210 G before policy-wide modifiers and fee");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
    it.todo("cursed sword with enchantment 5 → both curse and high-enchantment surcharges apply");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("customer with exactly 2 years with MHPCO → loyalty discount applies");
    it.todo("customer with 1 year → no loyalty discount");
    it.todo("premium yielding a fraction is rounded up in the MHPCO's favor (e.g. 197.5 → 198)");
    it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
    it.todo("long-standing customer's (3 years) second quote, cursed sword enchantment 7 → premium 160 G (follow-up discount, first insurance still applies)");
  });

  describe("claim — reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("rune, damage 200 G → payout 100 G");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("sword (500 G) and amulet (300 G) damaged in one event → payout 600 G (deductible per damaged item)");
    it.todo("payout yielding a fraction is rounded down in the MHPCO's favor (e.g. 350.5 → 350)");
  });

  describe("claim — cap", () => {
    it.todo("sword insured, claim reports remainingCap = 2000 G minus payout");
    it.todo("sword + amulet policy → cap 3200 G");
    it.todo("cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G (block affects premium only)");
    it.todo("two successive 1500 G claims on a sword → payouts 1400 G then 600 G, remaining cap 600 G then 0 G");
    it.todo("two swords insured → cap 4000 G; two sword damages each get their own deductible");
  });

  describe("scenario processing", () => {
    it.todo("results array has the same length and order as the steps (quote then claim)");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type (broomstick) → rejected with error");
    it.todo("claim damaging an item not in the policy (amulet when only sword insured) → rejected");
    it.todo("claim damaging an unknown item type → rejected");
    it.todo("claim with more damages of a type than insured (two swords, one insured) → rejected");
    it.todo("claim with negative damage amount (-200) → rejected");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin and writes results JSON to stdout");
    it.todo("exits non-zero and writes to stderr on an invalid scenario, no results on stdout");
  });
});
EOF

