export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioResult {
  results: object[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const quote = (step: QuoteStep): number => {
  const basePremium = step.items.length * 100;
  return basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
};
EOF
