export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioResult {
  results: object[];
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const quotePremium = (step: QuoteStep): number => {
  const basePremium = sumBasePremiums(step.items);
  return basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});
