  Math.floor(step.incident.damages.reduce((sum, damage) => sum + damagePayout(damage, policyItems), 0));

const insuredItems = (steps: Step[], policy: number): Item[] => (steps[policy] as QuoteStep).items;

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, index) =>
    step.op === "claim"
      ? { payout: claimPayout(step, insuredItems(scenario.steps, step.policy)) }
      : { premium: quotePremium(step, scenario.customer, isFollowUpContract(index)) },
  ),
});

